    def draw_map(self, canvas):
        canvas.delete("all")
        w = canvas.winfo_width()
        h = canvas.winfo_height()

        # Ilustrație decorativă, fără date geografice.
        canvas.create_oval(
            w * .04, h * .08, w * .38, h * .55,
            fill="#9DD0E5" if BG == LIGHT_THEME["BG"] else "#315D78", outline=""
        )
        canvas.create_oval(
            w * .65, h * .55, w * .98, h * .95,
            fill="#9DD0E5" if BG == LIGHT_THEME["BG"] else "#315D78", outline=""
        )

        for fraction in (.25, .55, .80):
            canvas.create_line(
                w * fraction, 0, w * (fraction - .12), h,
                fill="#F3FBFF" if BG == LIGHT_THEME["BG"] else "#D9ECF5", width=17
            )

        for fraction in (.30, .70):
            canvas.create_line(
                0, h * fraction, w, h * (fraction + .08),
                fill="#F3FBFF" if BG == LIGHT_THEME["BG"] else "#D9ECF5", width=17
            )

        route = [
            w * .16, h * .75,
            w * .36, h * .75,
            w * .48, h * .37,
            w * .80, h * .37,
        ]

        canvas.create_line(
            *route, fill="#2389BD" if BG == LIGHT_THEME["BG"] else "#65DDE8", width=7,
            capstyle="round", joinstyle="round"
        )

        for x, y, text in [
            (w * .16, h * .75, "Plecare"),
            (w * .80, h * .37, "Campus"),
        ]:
            canvas.create_oval(
                x - 8, y - 8, x + 8, y + 8,
                fill=ACCENT_GREEN, outline=WHITE, width=3,
            )
            canvas.create_text(
                x, y - 21, text=text,
                fill=TEXT, font=(FONT, 10, "bold")
            )

