    def arata_pasul(self):
        if not self.nav_steps:
            if hasattr(self, "nav_title"):
                self.nav_title.set("Calculează un traseu pentru indicații pas cu pas.")
                self.nav_counter.set("")
            return
        self.nav_index = max(0, min(self.nav_index, len(self.nav_steps) - 1))
        pas = self.nav_steps[self.nav_index]
        self.nav_title.set(pas["text"])
        mod = "Urmărire GPS activă" if self.nav_follow else "Parcurgere manuală"
        self.nav_counter.set(f"Pasul {self.nav_index + 1} din {len(self.nav_steps)} • {mod}")
        if self.nav_window is not None and self.nav_window.winfo_exists():
            self.nav_big_title.set(pas['text'])
            self.nav_big_counter.set(f'Pasul {self.nav_index + 1} din {len(self.nav_steps)}')
            # În navigația GPS urmărim poziția actuală, nu sărim la intersecții.
            # Fără salturi de cameră la manevre: harta se mișcă numai cu GPS.

    def pas_urmator(self):
        if self.nav_steps and self.nav_index < len(self.nav_steps) - 1:
            self.nav_index += 1
            self.arata_pasul()
            if self.nav_speech.get():
                self.citeste_pasul()

    def pas_anterior(self):
        if self.nav_steps and self.nav_index > 0:
            self.nav_index -= 1
            self.arata_pasul()
            if self.nav_speech.get():
                self.citeste_pasul()

    def citeste_pasul(self):
        if self.nav_steps:
            self._rosteste(self.nav_steps[self.nav_index]["text"])

    def _rosteste(self, mesaj):
        """Voce română neurală prin edge-tts, dacă este instalat și există internet.
        Fallback: voce română SAPI instalată; niciodată voce engleză neanunțată.
        """
        def worker():
            try:
                with self.speech_lock:
                    try:
                        import edge_tts
                        async def generate(path):
                            await edge_tts.Communicate(
                                text=mesaj, voice="ro-RO-AlinaNeural", rate="-5%"
                            ).save(path)
                        with tempfile.TemporaryDirectory(prefix="f1ve_dr1ve_voice_") as tmp:
                            audio = str(Path(tmp) / "navigatie.mp3")
                            asyncio.run(generate(audio))
                            # Windows MCI playback; blocks until narration finishes.
                            winmm = ctypes.windll.winmm
                            alias = "f1ve_dr1ve_voice"
                            def mci(command):
                                buffer = ctypes.create_unicode_buffer(512)
                                code = winmm.mciSendStringW(command, buffer, 511, 0)
                                if code:
                                    raise RuntimeError(f"Redare audio Windows: cod {code}")
                            mci(f'open "{audio}" type mpegvideo alias {alias}')
                            try:
                                mci(f'play {alias} wait')
                            finally:
                                mci(f'close {alias}')
                        return
                    except Exception as online_error:
                        # SAPI is used ONLY if Romanian voice is installed.
                        script = (
                            "Add-Type -AssemblyName System.Speech; "
                            "$v=New-Object System.Speech.Synthesis.SpeechSynthesizer; "
                            "$ro=$v.GetInstalledVoices() | Where-Object "
                            "{ $_.VoiceInfo.Culture.Name -eq 'ro-RO' } | Select-Object -First 1; "
                            "if (-not $ro) { exit 42 }; "
                            "$v.SelectVoice($ro.VoiceInfo.Name); $v.Volume=100; $v.Rate=-1; "
                            "$v.Speak('" + mesaj.replace("'", "''") + "')"
                        )
                        encoded = base64.b64encode(script.encode("utf-16le")).decode("ascii")
                        proc = subprocess.run(
                            ["powershell.exe", "-NoProfile", "-EncodedCommand", encoded],
                            capture_output=True, timeout=40
                        )
                        if proc.returncode == 42:
                            raise RuntimeError(
                                "Nu există voce română Windows. Instalează «edge-tts» "
                                "(python -m pip install edge-tts) și folosește internet, "
                                "sau instalează o voce SAPI ro-RO în Windows."
                            ) from online_error
                        if proc.returncode:
                            raise RuntimeError(proc.stderr.decode("utf-8", errors="replace")[-350:])
            except Exception as eroare:
                self.route_queue.put(("SPEECH_ERROR", f"Voce română indisponibilă: {eroare}"))
        threading.Thread(target=worker, daemon=True).start()

    def deschide_navigatia_3d(self, puncte, start, final):
        """MapLibre GL: navigație cu cameră înclinată, GPS din browser și voce RO.

        Pagina este servită exclusiv pe 127.0.0.1; coordonatele GPS nu sunt
        transmise serverului Python. Harta și geolocalizarea cer internet.
        """
        if len(puncte) < 2:
            messagebox.showwarning('F1VE DR1VE', 'Calculează mai întâi un traseu.')
            return
        coords = [[float(lon), float(lat)] for lat, lon in puncte]
        payload = json.dumps({'route': coords, 'start': [float(start[0]), float(start[1])],
                              'end': [float(final[0]), float(final[1])]}, ensure_ascii=False)
        html = _F1VE_MAPLIBRE_HTML.replace('__F1VE_DATA__', payload)
        class Handler(BaseHTTPRequestHandler):
            def do_GET(self):
                if self.path.split('?')[0] != '/':
                    self.send_error(404)
                    return
                content = html.encode('utf-8')
                self.send_response(200)
                self.send_header('Content-Type', 'text/html; charset=utf-8')
                self.send_header('Content-Length', str(len(content)))
                self.send_header('Cache-Control', 'no-store')
                self.end_headers()
                self.wfile.write(content)
            def log_message(self, *args):
                pass
        try:
            server = ThreadingHTTPServer(('127.0.0.1', 0), Handler)
            threading.Thread(target=server.serve_forever, daemon=True).start()
            url = 'http://127.0.0.1:%d/' % server.server_port
            if not webbrowser.open(url):
                # Pe unele sisteme webbrowser.open nu găsește browserul implicit.
                if os.name == 'nt':
                    os.startfile(url)
                else:
                    messagebox.showinfo('Navigație 3D', 'Deschide în browser: ' + url)
        except Exception as exc:
            messagebox.showerror('Navigație 3D', 'Nu am putut porni harta: ' + str(exc))

    def deschide_navigatia(self, puncte, start, final):
        """Navigația implicită este MapLibre 3D; nu mai deschidem harta Tkinter 2D."""
        self.deschide_navigatia_3d(puncte, start, final)

    def comuta_microfonul(self):
        """Activare explicită. Recunoașterea Google trimite audio către serviciu."""
        if self.nav_microphone_enabled:
            self.opreste_microfonul()
            return
        try:
            import speech_recognition as sr
            import pyaudio  # noqa: F401; necesar pentru sr.Microphone
        except ImportError:
            messagebox.showwarning(
                'Comenzi vocale',
                'Instalează: python -m pip install SpeechRecognition PyAudio\n'
                'Este necesar un microfon funcțional și internet pentru recunoașterea Google.',
                parent=self.nav_window)
            return
        consent = messagebox.askyesno(
            'Activare microfon',
            'Permiți ascultarea microfonului cât timp navigația este deschisă?\n\n'
            'Recunoașterea Google necesită internet și transmite fragmente audio '
            'către serviciul extern. Microfonul poate fi oprit oricând.\n\n'
            'Nu folosi comenzile vocale ca înlocuitor pentru atenția la drum.',
            parent=self.nav_window)
        if not consent:
            return
        self.nav_microphone_enabled = True
        self.nav_microphone_stop.clear()
        self.nav_mic_button.configure(text='⏹ Oprește microfonul')
        self.nav_voice_status.set('🎙 Ascultare activă • spune numele unui buton sau opusul său: «Anterior», «Următor», «Repetă indicația», «Oprește GPS», «Oprește vocea», «Oprește microfonul».')
        self.nav_microphone_thread = threading.Thread(target=self._bucla_comenzi_vocale, daemon=True)
        self.nav_microphone_thread.start()

    def opreste_microfonul(self):
        self.nav_microphone_enabled = False
        self.nav_microphone_stop.set()
        if self.nav_window is not None and self.nav_window.winfo_exists():
            if hasattr(self, 'nav_mic_button') and self.nav_mic_button.winfo_exists():
                self.nav_mic_button.configure(text='🎙 Activează comenzi vocale')
            if self.nav_voice_status is not None:
                self.nav_voice_status.set('Microfon oprit.')

    def _bucla_comenzi_vocale(self):
        import speech_recognition as sr
        recognizer = sr.Recognizer()
        recognizer.dynamic_energy_threshold = True
        # Comenzile scurte se încheie mai rapid, fără a aștepta aproape o secundă
        # de tăcere. În medii zgomotoase poate fi necesară o pauză mai lungă.
        recognizer.pause_threshold = 0.45
        recognizer.non_speaking_duration = 0.25
        recognizer.phrase_threshold = 0.2
        recognizer.operation_timeout = 4
        try:
            with sr.Microphone() as source:
                recognizer.adjust_for_ambient_noise(source, duration=0.3)
                while not self.nav_microphone_stop.is_set():
                    try:
                        audio = recognizer.listen(source, timeout=0.8, phrase_time_limit=3)
                    except sr.WaitTimeoutError:
                        continue
                    if self.nav_microphone_stop.is_set():
                        break
                    try:
                        text = recognizer.recognize_google(audio, language='ro-RO')
                    except sr.UnknownValueError:
                        continue
                    except sr.RequestError as exc:
                        self.route_queue.put(('VOICE_MIC_ERROR', 'Serviciul de recunoaștere nu răspunde: ' + str(exc)))
                        break
                    self.route_queue.put(('VOICE_COMMAND', text))
        except Exception as exc:
            self.route_queue.put(('VOICE_MIC_ERROR', str(exc)))

    def executa_comanda_vocala(self, heard):
        """Comenzi cu denumirile butoanelor de navigație și opusele lor."""
        if not self.nav_microphone_enabled or not self.nav_window or not self.nav_window.winfo_exists():
            return
        normalized = unicodedata.normalize('NFD', heard.lower())
        normalized = ''.join(ch for ch in normalized if unicodedata.category(ch) != 'Mn')
        normalized = ' '.join(normalized.split())
        # Evită declanșările duble; verifică întâi expresiile lungi și comenzile de oprire.
        now = time.monotonic()
        if self.nav_last_voice_command[0] == normalized and now - self.nav_last_voice_command[1] < 1.8:
            return
        self.nav_last_voice_command = (normalized, now)

        def spus(*expresii):
            return any(re.search(r'(?<!\w)' + re.escape(x) + r'(?!\w)', normalized) for x in expresii)

        if spus('opreste comenzile vocale', 'dezactiveaza comenzile vocale',
                 'opreste microfonul', 'dezactiveaza microfonul', 'opreste ascultarea'):
            self.opreste_microfonul()
            return
        elif spus('inchide navigatia', 'opreste navigatia'):
            self.inchide_navigatia()
            return
        elif spus('opreste urmarirea gps', 'opreste gps', 'opreste urmarirea',
                   'dezactiveaza gps', 'opreste localizarea'):
            if self.nav_follow:
                self.comuta_urmarirea_gps()
            status = 'Urmărirea GPS este oprită.'
        elif spus('porneste urmarirea gps', 'porneste gps', 'porneste urmarirea',
                   'activeaza gps', 'activeaza urmarirea gps'):
            if not self.nav_follow:
                self.comuta_urmarirea_gps()
            status = 'Urmărirea GPS este activată.'
        elif spus('opreste vocea', 'dezactiveaza vocea', 'voce oprita',
                   'fara voce', 'opreste indicatiile vocale'):
            self.nav_speech.set(False)
            status = 'Voce dezactivată.'
        elif spus('porneste vocea', 'activeaza vocea', 'voce activa',
                   'porneste indicatiile vocale'):
            self.nav_speech.set(True)
            status = 'Voce activată.'
        elif spus('repeta indicatia', 'repeta', 'citeste indicatia', 'citeste pasul'):
            self.citeste_pasul()
            status = 'Indicația a fost repetată.'
        elif spus('pasul anterior', 'anterior', 'inapoi un pas', 'mergi inapoi'):
            self.pas_anterior()
            status = 'Pasul anterior.'
        elif spus('urmatorul pas', 'urmator', 'pasul urmator', 'mai departe'):
            self.pas_urmator()
            status = 'Pasul următor.'
        else:
            status = 'Comandă neidentificată: ' + heard[:75]
        if self.nav_voice_status is not None:
            self.nav_voice_status.set('🎙 ' + status)

    def comuta_urmarirea_gps(self):
        """Urmărirea pornește numai la alegerea explicită a utilizatorului."""
        if self.nav_follow:
            self.nav_follow = False
            self.nav_gps_button.configure(text='📍 Pornește urmărirea GPS')
            if self.nav_gps_after is not None:
                self.after_cancel(self.nav_gps_after)
                self.nav_gps_after = None
            self.nav_big_counter.set('Urmărirea GPS este oprită.')
        else:
            self.nav_follow = True
            self.nav_gps_button.configure(text='⏹ Oprește urmărirea GPS')
            self.nav_big_counter.set('Se solicită poziția Windows...')
            self.actualizeaza_navigatia_gps()
        self.arata_pasul()

    def inchide_navigatia(self):
        self.opreste_microfonul()
        self.nav_follow = False
        if self.nav_animation_after is not None:
            try:
                self.after_cancel(self.nav_animation_after)
            except Exception:
                pass
            self.nav_animation_after = None
        if self.nav_gps_after is not None:
            self.after_cancel(self.nav_gps_after)
            self.nav_gps_after = None
        if self.nav_window is not None and self.nav_window.winfo_exists():
            self.nav_window.destroy()
        self.nav_window = None
        self.nav_big_map = None

    def actualizeaza_navigatia_gps(self):
        """Urmărește locația numai dacă utilizatorul a ales explicit Windows."""
        if not self.nav_follow or self.nav_window is None or not self.nav_window.winfo_exists():
            return
        if not self.nav_gps_busy:
            self.nav_gps_busy = True
            threading.Thread(target=self._citeste_locatia_windows, daemon=True).start()
        self.nav_gps_after = self.after(5000, self.actualizeaza_navigatia_gps)

    @staticmethod
    def _directie_grade(lat1, lon1, lat2, lon2):
        """Azimut 0=nord, 90=est; calculat din deplasarea GPS."""
        a, b = math.radians(lat1), math.radians(lat2)
        dl = math.radians(lon2 - lon1)
        y = math.sin(dl) * math.cos(b)
        x = math.cos(a)*math.sin(b)-math.sin(a)*math.cos(b)*math.cos(dl)
        return (math.degrees(math.atan2(y, x)) + 360) % 360

    def _icon_masina(self, heading):
        """Mașinuță desenată local; nu necesită un fișier imagine separat."""
        try:
            from PIL import Image, ImageDraw, ImageTk
            key = int(round(heading / 10)) * 10 % 360
            if key not in self.nav_car_icons:
                im = Image.new('RGBA', (80, 80), (0, 0, 0, 0))
                d = ImageDraw.Draw(im)
                d.ellipse((21, 10, 59, 71), fill='#10283F', outline='#4EE9F1', width=3)
                d.rounded_rectangle((27, 15, 53, 65), radius=9, fill='#F2768E', outline='white', width=2)
                d.rounded_rectangle((31, 24, 49, 38), radius=4, fill='#173C57')
                d.rounded_rectangle((31, 47, 49, 56), radius=3, fill='#173C57')
                d.polygon([(40, 2), (31, 16), (49, 16)], fill='#4EE9F1')
                # Imaginea inițială indică nordul; PIL rotește antiorar.
                im = im.rotate(-key, resample=Image.Resampling.BICUBIC)
                self.nav_car_icons[key] = ImageTk.PhotoImage(im)
            return self.nav_car_icons[key]
        except Exception:
            return None

    def _animeaza_masina(self):
        self.nav_animation_after = None
        if not self.nav_follow or self.nav_big_map is None or not self.nav_big_map.winfo_exists():
            return
        if self.nav_anim_target is None:
            return
        if self.nav_anim_position is None:
            self.nav_anim_position = self.nav_anim_target
        old_lat, old_lon = self.nav_anim_position
        dest_lat, dest_lon = self.nav_anim_target
        # Mișcare interpolată pentru a evita salturile între citirile GPS.
        alpha = 0.22
        lat = old_lat + (dest_lat-old_lat)*alpha
        lon = old_lon + (dest_lon-old_lon)*alpha
        if self.distanta_metri(lat, lon, dest_lat, dest_lon) < 0.8:
            lat, lon = dest_lat, dest_lon
        self.nav_anim_position = (lat, lon)
        icon = self._icon_masina(self.nav_heading)
        if self.nav_big_marker is None:
            kw = {'icon': icon, 'icon_anchor': 'center'} if icon else {'text': '🚗'}
            self.nav_big_marker = self.nav_big_map.set_marker(lat, lon, **kw)
            if not self.nav_last_camera_zoom:
                self.nav_big_map.set_zoom(17)
                self.nav_last_camera_zoom = True
        else:
            self.nav_big_marker.set_position(lat, lon)
            if icon:
                try:
                    self.nav_big_marker.change_icon(icon)
                except Exception:
                    pass
        # Harta urmărește automobilul, nu punctele de manevră.
        self.nav_big_map.set_position(lat, lon)
        self.nav_animation_after = self.after(220, self._animeaza_masina)

    @staticmethod
    def _proiectie_pe_segment(lat, lon, a, b):
        """Proiecție locală aproximativă în metri pe segmentul unei rute."""
        kx = 111320.0 * max(0.01, math.cos(math.radians(lat)))
        ky = 111195.0
        ax, ay = (a[1]-lon)*kx, (a[0]-lat)*ky
        bx, by = (b[1]-lon)*kx, (b[0]-lat)*ky
        vx, vy = bx-ax, by-ay
        t = max(0.0, min(1.0, -(ax*vx+ay*vy)/(vx*vx+vy*vy))) if vx*vx+vy*vy else 0.0
        px, py = ax+t*vx, ay+t*vy
        return math.hypot(px, py), (lat+py/ky, lon+px/kx), t

    def _pozitie_pe_traseu(self, lat, lon):
        """Returnează distanța laterală, punctul proiectat și distanța rămasă."""
        points = self.nav_route_points
        if len(points) < 2:
            return float('inf'), (lat, lon), 0.0
        best = (float('inf'), (lat, lon), 0.0)
        cumulative = [0.0]
        for a, b in zip(points, points[1:]):
            cumulative.append(cumulative[-1] + self.distanta_metri(*a, *b))
        for i, (a, b) in enumerate(zip(points, points[1:])):
            d, projected, t = self._proiectie_pe_segment(lat, lon, a, b)
            if d < best[0]:
                remaining = cumulative[-1] - (cumulative[i] + t*(cumulative[i+1]-cumulative[i]))
                best = (d, projected, max(0.0, remaining))
        return best

    def navigheaza_cu_pozitia(self, lat, lon, accuracy):
        """GPS real, interpolare vizuală, estimare viteză și apropiere de manevre."""
        self.nav_gps_busy = False
        if not self.nav_follow or self.nav_big_map is None or not self.nav_big_map.winfo_exists():
            return
        if not all(math.isfinite(v) for v in (lat, lon, accuracy)):
            return
        now = time.monotonic()
        if self.nav_prev_fix is not None and self.nav_prev_fix_time is not None:
            old_lat, old_lon = self.nav_prev_fix
            moved = self.distanta_metri(old_lat, old_lon, lat, lon)
            dt = max(0.1, now-self.nav_prev_fix_time)
            # Viteza GPS e afișată numai dacă eroarea e rezonabilă.
            if accuracy <= 25 and moved >= max(7.0, accuracy*0.65):
                measured = moved/dt*3.6
                if measured <= 160:
                    self.nav_speed_kmh = 0.55*self.nav_speed_kmh + 0.45*measured
                    self.nav_heading = self._directie_grade(old_lat, old_lon, lat, lon)
            elif moved < 4 and dt >= 3:
                self.nav_speed_kmh *= 0.5
        self.nav_prev_fix = (lat, lon)
        self.nav_prev_fix_time = now
        self.nav_last_position = (lat, lon)
        self.nav_last_gps_time = datetime.now()
        self.nav_position_history.append((lat, lon, accuracy))
        self.nav_position_history = self.nav_position_history[-6:]

        lateral, projected, remaining = self._pozitie_pe_traseu(lat, lon)
        # Nu falsificăm poziția: proiectăm mașina pe drum doar dacă GPS e suficient de precis.
        snapped = accuracy <= 20 and lateral <= max(12, accuracy*1.4)
        self.nav_anim_target = projected if snapped else (lat, lon)
        if self.nav_animation_after is None:
            self._animeaza_masina()

        if accuracy <= 25:
            speed = f'{self.nav_speed_kmh:.0f} km/h'
        else:
            speed = '— (GPS imprecis)'
        eta = '—'
        if remaining > 0 and self.nav_speed_kmh >= 5 and accuracy <= 25:
            minutes = remaining / (self.nav_speed_kmh/3.6) / 60
            if minutes <= 180:
                eta = (datetime.now() + timedelta(minutes=minutes)).strftime('%H:%M')
        self.nav_live_stats.set(
            f'🚗 {speed}  •  Rămas: {remaining/1000:.1f} km  •  Sosire estimată: {eta}  •  GPS ±{accuracy:.0f} m')
        if accuracy > self.nav_gps_accuracy_limit:
            self.nav_big_counter.set('GPS prea imprecis pentru manevre automate. Verifică poziția pe hartă.')
            return
        if lateral > max(55, accuracy*2.5) and now-self.nav_last_offroute_alert > 35:
            self.nav_last_offroute_alert = now
            self.nav_big_counter.set('⚠ Ai putea fi în afara traseului. Recalculează ruta din Rute & trafic.')
            if self.nav_speech.get():
                self._rosteste('Atenție. Poți fi în afara traseului. Verifică ruta.')
            return
        if not self.nav_steps:
            self.nav_big_counter.set(f'GPS ±{accuracy:.0f} m • urmărire automată')
            return
        next_idx = min(self.nav_index+1, len(self.nav_steps)-1)
        target = self.nav_steps[next_idx].get('location')
        if not target:
            return
        distance = self.distanta_metri(lat, lon, *target)
        self.nav_big_counter.set(
            f'{distance:.0f} m până la următoarea manevră  •  pasul {self.nav_index+1}/{len(self.nav_steps)}')
        if 90 <= distance <= 220 and next_idx not in self.nav_approach_announced:
            self.nav_approach_announced.add(next_idx)
            if self.nav_speech.get():
                self._rosteste(f'În aproximativ {round(distance/10)*10} de metri. '
                              + self.nav_steps[next_idx]['text'].split(' • ')[0])
        if (distance <= 35 and self.nav_index < len(self.nav_steps)-1
                and len(self.nav_position_history) >= 2
                and self.nav_position_history[-2][2] <= self.nav_gps_accuracy_limit
                and self.distanta_metri(*self.nav_position_history[-2][:2], lat, lon) >= 5):
            self.nav_index += 1
            self.arata_pasul()
            if self.nav_speech.get():
                self.citeste_pasul()

    @staticmethod
    def distanta_metri(lat1, lon1, lat2, lon2):
        r = 6371000
        a = (math.sin(math.radians(lat2-lat1)/2)**2 +
             math.cos(math.radians(lat1))*math.cos(math.radians(lat2))*
             math.sin(math.radians(lon2-lon1)/2)**2)
        return 2*r*math.asin(min(1, math.sqrt(a)))

    def vezi_istoric_rute(self):
        with deschide_baza() as db:
            rows = db.execute("""SELECT origine, destinatie, plecare, distanta_km,
                sosire_normala, sosire_prudenta FROM istoric_trasee
                ORDER BY id DESC LIMIT 8""").fetchall()
        if not rows:
            messagebox.showinfo("Istoric trasee", "Nu ai calculat încă niciun traseu.", parent=self)
            return
        lines = [f"{a} → {b}\n  Plecare {t} • {km:.1f} km • "
                 f"sosire normală {n} / prudentă {pr}"
                 for a, b, t, km, n, pr in rows]
        messagebox.showinfo("Ultimele trasee salvate local", "\n\n".join(lines), parent=self)

    def afiseaza_rute(self, text):
        if not hasattr(self, "route_results") or not self.route_results.winfo_exists():
            return
        self.route_results.configure(state="normal")
        self.route_results.delete("1.0", "end")
        self.route_results.insert("1.0", text)
        self.route_results.configure(state="disabled")

    def porneste_rute(self):
        if self.route_busy:
            return
        origine = self.origine.get().strip()
        destinatie = self.destinatie.get().strip()
        coordonate_dispozitiv = self.device_coords if origine == "📍 Locația dispozitivului" else None
        if not origine or not destinatie:
            self.route_status.set("⚠ Completează ambele adrese.")
            return
        try:
            plecare = datetime.strptime(self.ora_plecare.get().strip(), "%H:%M")
            if self.ora_plecare.get().strip() != plecare.strftime("%H:%M"):
                raise ValueError()
        except ValueError:
            self.route_status.set("⚠ Ora plecării trebuie să fie HH:MM, de exemplu 09:15.")
            return
        self.route_busy = True
        self.route_status.set("Calculăm variantele OSRM pentru comparare...")
        self.route_text = "Se încarcă rezultatele..."
        self.afiseaza_rute(self.route_text)
        self.route_button.configure(state="disabled", text="Se calculează...")
        threading.Thread(
            target=self.lucrator_rute, args=(origine, destinatie, coordonate_dispozitiv,
                                                  self.ora_plecare.get().strip()), daemon=True,
        ).start()
        self.after(35000, self._verifica_timeout_ruta)

    def _verifica_timeout_ruta(self):
        if self.route_busy:
            self.route_busy = False
            self.route_status.set("Calculul durează prea mult. Poți încerca din nou; verifică și conexiunea.")
            if hasattr(self, "route_button") and self.route_button.winfo_exists():
                self.route_button.configure(state="normal", text="Calculează traseul  →")

    def lucrator_rute(self, origine, destinatie, coordonate_dispozitiv=None, ora_plecare="09:00"):
        # Toate operațiile Tkinter se execută doar în firul principal.
        try:
            if coordonate_dispozitiv is not None:
                start = coordonate_dispozitiv
            else:
                start = coordonate(origine)
                if destinatie.strip().casefold() not in CACHE_ADRESE:
                    time.sleep(1.1)  # Respectăm limita Nominatim public.
            final = coordonate(destinatie)
            rute = calculeaza_rute(start, final)
            linii = []
            coeficient = 1.0  # OSRM, fără scenariu de trafic inventat
            for i, ruta in enumerate(rute[:2], 1):
                linii.append(
                    f"Varianta {i}  •  {ruta['distance']/1000:.1f} km"
                    f"  •  {math.ceil(ruta['duration']/60)} min (estimare OSRM, fără trafic live)"
                )
            rapida = min(rute, key=lambda ruta: ruta["duration"])
            scurta = min(rute, key=lambda ruta: ruta["distance"])
            durata_normala = max(1, math.ceil(rapida["duration"] / 60 * coeficient))
            durata_prudenta = math.ceil(durata_normala * 1.2 + 5)
            baza = datetime.strptime(ora_plecare, "%H:%M")
            sosire_normala = (baza + timedelta(minutes=durata_normala)).strftime("%H:%M")
            sosire_prudenta = (baza + timedelta(minutes=durata_prudenta)).strftime("%H:%M")
            linii.extend([
                "", "PREDICȚIA 1 — ORA SOSIRII (estimare OSRM, fără trafic live):",
                f"🕒 Plecare: {ora_plecare}",
                f"Estimare OSRM: {durata_normala} min • sosire {sosire_normala}",
                f"Marjă orientativă: {durata_prudenta} min • sosire {sosire_prudenta}",
                "Marja orientativă adaugă 20% + 5 min; nu reprezintă trafic măsurat.",
                "",
                f"⚡ Cea mai rapidă: {rapida['distance']/1000:.1f} km, "
                f"{math.ceil(rapida['duration']/60)} minute",
                f"📏 Cea mai scurtă: {scurta['distance']/1000:.1f} km, "
                f"{math.ceil(scurta['duration']/60)} minute",
                "",
                "Estimările nu includ trafic live sau așteptarea unui șofer.",
                "PREDICȚIA 2 — TRASEU: comparăm două drumuri OSRM către aceeași destinație, dacă există.",
            ])
            linii.extend(["", "INDICAȚII DE DEPLASARE (traseul cel mai rapid):"])
            pasi_navigatie = []
            for leg in rapida.get("legs", []):
                for pas in leg.get("steps", []):
                    manevra = pas.get("maneuver", {})
                    tip = manevra.get("type", "continue")
                    directie = manevra.get("modifier", "")
                    strada = pas.get("name") or "drumul indicat"
                    directii = {"left": "la stânga", "right": "la dreapta",
                               "straight": "înainte", "slight left": "ușor la stânga",
                               "slight right": "ușor la dreapta", "sharp left": "accentuat la stânga",
                               "sharp right": "accentuat la dreapta", "uturn": "înapoi"}
                    orientare = directii.get(directie, "")
                    if tip == "depart":
                        instructiune = f"Pornește pe {strada}"
                    elif tip == "arrive":
                        instructiune = "Ai ajuns la destinație"
                    elif tip in ("turn", "end of road"):
                        instructiune = f"Virează {orientare} pe {strada}"
                    elif tip == "roundabout":
                        iesire = manevra.get("exit")
                        instructiune = f"Intră în sensul giratoriu" + (f" și ieși la ieșirea {iesire}" if iesire else "")
                    elif tip in ("fork", "merge", "on ramp", "off ramp"):
                        instructiune = f"Urmează {orientare} spre {strada}"
                    else:
                        instructiune = f"Continuă {orientare} pe {strada}"
                    distanta = float(pas.get("distance", 0))
                    if tip != "arrive":
                        instructiune += f" • {distanta:.0f} m până la următoarea manevră"
                    location = manevra.get("location")
                    coord = (float(location[1]), float(location[0])) if location and len(location) == 2 else None
                    pasi_navigatie.append({"text": instructiune, "location": coord})
                    linii.append(f" • {instructiune}")
            geometrie = rapida.get("geometry", {}).get("coordinates", [])
            puncte = [(lat, lon) for lon, lat in geometrie]
            # Salvăm doar adresele introduse; coordonatele Windows nu intră în baza locală.
            with deschide_baza() as db:
                db.execute("""INSERT INTO istoric_trasee
                    (origine, destinatie, plecare, distanta_km, durata_min,
                     sosire_normala, sosire_prudenta, creat_la)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                    ("Locația dispozitivului" if coordonate_dispozitiv is not None else origine,
                     destinatie, ora_plecare, round(rapida["distance"] / 1000, 2),
                     durata_normala, sosire_normala, sosire_prudenta,
                     datetime.now().isoformat(timespec="seconds")))
            optiuni = []
            for ruta in rute[:2]:
                geometrie_opt = ruta.get("geometry", {}).get("coordinates", [])
                puncte_opt = [(lat, lon) for lon, lat in geometrie_opt]
                stare, acoperire = trafic_colaborativ(puncte_opt)
                optiuni.append({"puncte": puncte_opt,
                                "km": ruta["distance"] / 1000,
                                "minute": math.ceil(ruta["duration"] / 60 * coeficient),
                                "trafic": stare, "acoperire": acoperire})
            with deschide_baza() as db:
                stamp = datetime.now().isoformat(timespec="seconds")
                db.execute("INSERT INTO predictii (origine,destinatie,plecare,tip,rezultat,metoda,creat_la) VALUES (?,?,?,?,?,?,?)",
                           (origine, destinatie, ora_plecare, "ora", sosire_normala, "OSRM fără trafic live", stamp))
                db.execute("INSERT INTO predictii (origine,destinatie,plecare,tip,rezultat,metoda,creat_la) VALUES (?,?,?,?,?,?,?)",
                           (origine, destinatie, ora_plecare, "traseu", "Compararea a două alternative OSRM", "Durată OSRM, fără trafic live și fără ML", stamp))
            if len(optiuni) >= 2:
                linii.insert(0, "Două drumuri alternative disponibile. Recomandarea inițială este cea cu timpul OSRM mai mic.")
            else:
                linii.insert(0, "OSRM a returnat doar un drum distinct; nu inventăm al doilea traseu.")
            self.route_queue.put(("ROUTE_OK", "\n".join(linii),
                                  "Traseele au fost calculate cu succes! 💚", puncte, start, final,
                                  pasi_navigatie, optiuni))
        except Exception as eroare:
            self.route_queue.put((
                f"Nu am putut calcula traseul.\n{eroare}",
                "Verifică adresele sau conexiunea la internet.",
            ))

    def arata_optiuni_trasee(self):
        """Afișează cele două opțiuni ÎNAINTE de hartă, cu acțiunea Google Maps vizibilă."""
        frame = getattr(self, "route_choices_frame", None)
        if frame is None or not frame.winfo_exists():
            return
        for copil in frame.winfo_children():
            copil.destroy()
        tk.Label(frame, text="ALEGE RUTA  •  compară înainte de navigare",
                 bg="#1B3448", fg="#F5FAFF", font=(FONT, 11, "bold"),
                 anchor="w").pack(fill="x", pady=(0, 3))
        if not self.route_options:
            tk.Label(frame, text="Calculează traseul ca să vezi distanța, durata și traficul fiecărei variante.",
                     bg="#1B3448", fg="#D5E9F5", font=(FONT, 9),
                     anchor="w").pack(fill="x", pady=(0, 4))
        else:
            rand = tk.Frame(frame, bg="#1B3448")
            rand.pack(fill="x")
            for i, ruta in enumerate(self.route_options[:2]):
                selected = i == self.selected_route_index
                fundal = "#185264" if selected else "#122A40"
                card = tk.Frame(rand, bg=fundal, padx=10, pady=4,
                                highlightbackground="#38D8DC" if selected else "#34556B",
                                highlightthickness=2 if selected else 1)
                card.pack(side="left", fill="both", expand=True, padx=(0, 7) if i == 0 else (7, 0))
                tk.Label(card, text=("✓  " if selected else "○  ") + f"RUTA {i+1}" +
                         ("  • RECOMANDATĂ" if i == 0 else "  • ALTERNATIVĂ"),
                         bg=fundal, fg="#70F5F4" if selected else "#FFFFFF",
                         font=(FONT, 11, "bold"), anchor="w").pack(fill="x")
                trafic = ruta.get("trafic", "Necunoscut")
                if trafic not in ("Liber", "Moderat", "Aglomerat"):
                    trafic = "Necunoscut"
                tk.Label(card, text=f"{ruta['km']:.2f} km   •   {ruta['minute']} min   •   Trafic: {trafic}",
                         bg=fundal, fg="#EBF7FF", font=(FONT, 11), anchor="w",
                         wraplength=390).pack(fill="x", pady=(1, 3))
                choose_button = button(card, "✓ Selectată" if selected else "Alege această rută",
                       lambda j=i: self.alege_traseu(j),
                       "#27637B" if selected else ACCENT_GREEN, WHITE)
                choose_button.configure(pady=6)
                choose_button.pack(fill="x")
            if len(self.route_options) < 2:
                tk.Label(frame, text="OSRM a găsit o singură rută distinctă.",
                         bg="#1B3448", fg=MUTED, font=(FONT, 9)).pack(anchor="w")
        tk.Label(frame, text="Traficul apare necunoscut fără date reale. Google Maps își poate calcula propria rută.",
                 bg="#1B3448", fg="#D5E9F5", font=(FONT, 9), anchor="w").pack(fill="x", pady=(5, 0))
        if hasattr(self, "maps_primary_button") and self.maps_primary_button.winfo_exists():
            if self.route_options and getattr(self, "maps_destination_coords", None):
                self.maps_primary_button.configure(state="normal", text=f"↗ NAVIGHEAZĂ CU GOOGLE MAPS  •  RUTA {self.selected_route_index+1}")
            else:
                self.maps_primary_button.configure(state="disabled", text="↗ NAVIGHEAZĂ CU GOOGLE MAPS  •  CALCULEAZĂ TRASEUL")

    def deschide_google_maps(self, index=None, mod_trafic=False):
        """Deschide Google Maps cu plecare, destinație și un reper via orientativ.

        Google Maps recalculează ruta; un singur waypoint NU impune geometria OSRM.
        """
        import webbrowser
        from urllib.parse import urlencode
        if index is not None:
            self.selected_route_index = index
        final = getattr(self, "maps_destination_coords", None)
        params = {"api": "1", "travelmode": "driving"}
        if final:
            lon, lat = final  # OSRM: (lon, lat)
            params["destination"] = f"{lat:.7f},{lon:.7f}"
            start = getattr(self, "maps_origin_coords", None)
            if start:
                start_lon, start_lat = start
                params["origin"] = f"{start_lat:.7f},{start_lon:.7f}"
        elif mod_trafic:
            # Traffic view must be available even before calling the OSRM router.
            origine_text = self.origine.get().strip()
            destinatie_text = self.destinatie.get().strip()
            if not origine_text or not destinatie_text:
                messagebox.showwarning("Google Maps", "Completează plecarea și destinația.", parent=self)
                return
            params["origin"] = origine_text
            params["destination"] = destinatie_text
        else:
            messagebox.showwarning("Google Maps", "Calculează întâi traseul.", parent=self)
            return

        # Un punct intermediar orientativ, la mijlocul DISTANȚEI pe ruta selectată.
        # Punctul poate influența traseul Google Maps, dar nu îl fixează exact.
        reper = None
        if 0 <= self.selected_route_index < len(self.route_options):
            puncte = self.route_options[self.selected_route_index].get("puncte", [])
            if len(puncte) >= 3:
                import math
                def metri(a, b):
                    lat1, lon1 = a
                    lat2, lon2 = b
                    dy = (lat2 - lat1) * 111195.0
                    dx = (lon2 - lon1) * 111195.0 * math.cos(math.radians((lat1 + lat2) / 2))
                    return math.hypot(dx, dy)
                total = sum(metri(puncte[k-1], puncte[k]) for k in range(1, len(puncte)))
                parcurs = 0.0
                for k in range(1, len(puncte)):
                    parcurs += metri(puncte[k-1], puncte[k])
                    if parcurs >= total / 2:
                        reper = puncte[k]
                        break
                if reper and total >= 600:
                    params["waypoints"] = f"{reper[0]:.7f},{reper[1]:.7f}"
        url = "https://www.google.com/maps/dir/?" + urlencode(params)
        if mod_trafic:
            mesaj = (
                "Se deschide Google Maps cu plecarea și destinația.\n\n"
                "În Google Maps, apasă «Straturi» → «Trafic» pentru a vedea "
                "aglomerația pe străzi în timp real (dacă există date).\n\n"
                "Google Maps își calculează propria rută; nu garantează "
                "traseul OSRM selectat.\n\nDeschidem Google Maps?"
            )
        else:
            mesaj = ("Se deschide Google Maps cu plecarea și destinația" +
                     (" și un punct intermediar orientativ de pe ruta aleasă" if "waypoints" in params else "") +
                     ".\n\nGoogle Maps poate recalcula un alt drum; nu se poate transfera "
                     "garantat traseul exact din F1VE DR1VE.\n\nContinuăm?")
        if messagebox.askokcancel("Deschide Google Maps", mesaj, parent=self):
            if not webbrowser.open(url):
                messagebox.showinfo("Google Maps", "Deschide acest link în browser:\n" + url, parent=self)

    @staticmethod
    def culoare_trafic(stare):
        return {"Liber": "#28A745", "Moderat": "#E5B700", "Aglomerat": "#D32F2F"}.get(stare, "#748697")

    def deschide_harta_mare(self):
        """Fereastră de hartă mare; folosește rutele existente, fără recalculare."""
        if tkintermapview is None:
            messagebox.showwarning("Hartă", "Instalează tkintermapview pentru afișarea hărții.", parent=self)
            return
        fereastra = tk.Toplevel(self)
        fereastra.title("F1VE DR1VE • Hartă mare")
        fereastra.geometry("1250x800")
        fereastra.configure(bg="#0B1D30")
        bara = tk.Frame(fereastra, bg="#122A40", padx=12, pady=9)
        bara.pack(fill="x")
        tk.Label(bara, text="F1VE DR1VE  •  HARTĂ INTERACTIVĂ",
                 bg="#122A40", fg="#64E9EB", font=(FONT, 14, "bold")).pack(side="left")
        button(bara, "Navighează cu Google Maps ↗",
               lambda: self.deschide_google_maps(self.selected_route_index),
               "#29D5DB", "#092134").pack(side="right", padx=6)
        if not self.route_options:
            tk.Label(bara, text="Calculează mai întâi un traseu în pagina principală.",
                     bg="#122A40", fg=TEXT).pack(side="right", padx=12)
        harta = tkintermapview.TkinterMapView(fereastra, width=1200, height=700, corner_radius=0)
        harta.pack(fill="both", expand=True, padx=9, pady=9)
        harta.set_tile_server("https://a.tile.openstreetmap.org/{z}/{x}/{y}.png", max_zoom=19)
        if self.route_options:
            toate = []
            for i, ruta in reversed(list(enumerate(self.route_options[:2]))):
                puncte = ruta.get("puncte", [])
                if len(puncte) > 1:
                    toate.extend(puncte)
                    harta.set_path(self.puncte_pentru_harta(puncte),
                                   color=self.culoare_trafic(ruta.get("trafic")),
                                   width=8 if i == self.selected_route_index else 5)
            if toate:
                harta.set_marker(toate[0][0], toate[0][1], text="Plecare")
                harta.set_marker(toate[-1][0], toate[-1][1], text="Destinație")
                harta.fit_bounding_box((max(a for a,b in toate), min(b for a,b in toate)),
                                       (min(a for a,b in toate), max(b for a,b in toate)))
        else:
            harta.set_position(47.1585, 27.6014)
            harta.set_zoom(12)

    def alege_traseu(self, index):
        if index >= len(self.route_options):
            return
        self.selected_route_index = index
        ruta = self.route_options[index]
        harta = getattr(self, "route_map", None)
        if harta is not None and harta.winfo_exists() and len(ruta["puncte"]) > 1:
            harta.delete_all_path()
            harta.set_path(self.puncte_pentru_harta(ruta["puncte"]), color=self.culoare_trafic(ruta["trafic"]), width=6)
            puncte = ruta["puncte"]
            harta.fit_bounding_box((max(x for x,y in puncte), min(y for x,y in puncte)),
                                   (min(x for x,y in puncte), max(y for x,y in puncte)))
        self.arata_optiuni_trasee()
        self.route_status.set("Ruta selectată. Butonul Google Maps este deasupra rutelor; Maps poate recalcula drumul.")

    @staticmethod
    def puncte_pentru_harta(puncte, limita=650):
        """Reduce costul desenarii in Tkinter, fara a altera ruta GPS originala."""
        if len(puncte) <= limita:
            return puncte
        pas = max(1, math.ceil((len(puncte) - 1) / (limita - 1)))
        rezultat = puncte[::pas]
        if rezultat[-1] != puncte[-1]:
            rezultat.append(puncte[-1])
        return rezultat

    def verifica_rute(self):
        try:
            while True:
                mesaj = self.route_queue.get_nowait()
                if mesaj[0] == "ACCOUNT_OK":
                    self.account_token = mesaj[1]["access_token"]
                    self.account_user = mesaj[1]["user"]
                    self.refresh_profile_widgets()
                    self.show_page("Profil")
                    messagebox.showinfo("F1VE DR1VE", "Cont creat / conectare reușită!", parent=self)
                    continue
                if mesaj[0] == "ACCOUNT_ERROR":
                    messagebox.showerror("Cont F1VE DR1VE", mesaj[1], parent=self)
                    continue
                if mesaj[0] == 'VOICE_COMMAND':
                    self.executa_comanda_vocala(mesaj[1])
                    continue
                if mesaj[0] == 'VOICE_MIC_ERROR':
                    self.opreste_microfonul()
                    self.route_status.set('Microfon: ' + mesaj[1])
                    if self.nav_window is not None and self.nav_window.winfo_exists():
                        self.nav_voice_status.set('Eroare microfon: ' + mesaj[1][:160])
                    continue
                if mesaj[0] == "SPEECH_ERROR":
                    self.route_status.set(mesaj[1])
                    continue
                if mesaj[0] == "LOCATION_ERROR":
                    self.nav_gps_busy = False
                    if self.nav_follow and self.nav_window is not None and self.nav_window.winfo_exists():
                        self.nav_big_counter.set('Localizarea Windows a eșuat. Verifică permisiunile.')
                    self.route_status.set(mesaj[1])
                    continue
                if mesaj[0] == "LOCATION":
                    _, lat, lon, accuracy = mesaj
                    self.device_coords = (lon, lat)
                    self.navigheaza_cu_pozitia(lat, lon, accuracy)
                    self.origine.set("📍 Locația dispozitivului")
                    if not self.nav_follow:
                        self.route_status.set(
                            f"Locație primită (precizie estimată ±{accuracy:.0f} m). "
                            "Apasă «Calculează traseul»."
                        )
                    if getattr(self, "route_map", None) is not None and self.route_map.winfo_exists():
                        self.route_map.set_position(lat, lon)
                        self.route_map.set_zoom(16)
                        self.route_map.delete_all_marker()
                        self.route_map.set_marker(lat, lon, text="Locația mea (aproximativ)")
                    continue
                if mesaj[0] == "ROUTE_OK":
                    _, self.route_text, status, puncte, start, final, self.nav_steps, self.route_options = mesaj
                    self.selected_route_index = 0
                    self.maps_destination_coords = final
                    self.maps_origin_coords = start
                    self.arata_optiuni_trasee()
                    self.nav_index = 0
                else:
                    self.route_text, status = mesaj[:2]
                    puncte = start = final = None
                    self.nav_steps = []
                # Calculul s-a incheiat: eliberam butonul INAINTE de desenarea hartii.
                self.route_busy = False
                if hasattr(self, "route_button") and self.route_button.winfo_exists():
                    self.route_button.configure(state="normal", text="Calculează traseul  →")
                self.afiseaza_rute(self.route_text)
                self.route_status.set(status)
                if (puncte is not None and getattr(self, "route_map", None) is not None
                        and self.route_map.winfo_exists()):
                    self.route_map.delete_all_path()
                    self.route_map.delete_all_marker()
                    self.route_map.set_marker(start[1], start[0], text="Plecare")
                    self.route_map.set_marker(final[1], final[0], text="Destinație")
                    if len(puncte) >= 2:
                        for index, ruta in reversed(list(enumerate(self.route_options))):
                            if len(ruta["puncte"]) > 1:
                                self.route_map.set_path(self.puncte_pentru_harta(ruta["puncte"]), color=self.culoare_trafic(ruta["trafic"]), width=5 if index else 7)
                        self.route_map.fit_bounding_box(
                            (max(lat for lat, lon in puncte), min(lon for lat, lon in puncte)),
                            (min(lat for lat, lon in puncte), max(lon for lat, lon in puncte)),
                        )
                self.route_status.set(status)
                self.arata_pasul()
                # Nu deschidem automat navigația 3D. Utilizatorul compară
                # variantele și decide dacă deschide destinația în Google Maps.
        except queue.Empty:
            pass
        self.after(150, self.verifica_rute)

    def _deschide_navigatia_sigur(self, puncte, start, final):
        try:
            self.deschide_navigatia(puncte, start, final)
        except Exception as exc:
            self.route_status.set("Ruta a fost calculată, dar navigația nu s-a putut deschide: " + str(exc)[:180])

    def cere_locatia(self):
        """Citește poziția oferită de Windows, doar la apăsarea butonului."""
        self.route_status.set("Se solicită locația de la Windows...")
        threading.Thread(target=self._citeste_locatia_windows, daemon=True).start()

    def _citeste_locatia_windows(self):
        try:
            from winrt.windows.devices.geolocation import Geolocator

            async def obtine():
                locator = Geolocator()
                locator.desired_accuracy_in_meters = 25
                position = await asyncio.wait_for(
                    locator.get_geoposition_async(), timeout=30
                )
                point = position.coordinate.point.position
                accuracy = float(position.coordinate.accuracy)
                return float(point.latitude), float(point.longitude), accuracy

            lat, lon, accuracy = asyncio.run(obtine())
            if not (-90 <= lat <= 90 and -180 <= lon <= 180):
                raise ValueError("Windows a returnat coordonate invalide.")
            self.route_queue.put(("LOCATION", lat, lon, accuracy))
        except ImportError:
            self.route_queue.put(("LOCATION_ERROR",
                "Lipsește biblioteca Windows. Instalează: python -m pip install winrt-Windows.Devices.Geolocation"))
        except Exception as eroare:
            self.route_queue.put(("LOCATION_ERROR",
                "Windows nu a putut determina locația. Verifică permisiunile "
                "din Settings > Privacy & security > Location. "
                f"Detalii: {eroare}"))

    def inchide_aplicatia(self):
        self.opreste_microfonul()
        self.nav_follow = False
        if self.nav_gps_after is not None:
            self.after_cancel(self.nav_gps_after)
            self.nav_gps_after = None
        self.destroy()

